css:
.loader {
  display: flex;
  justify-content: center;
  align-items: center;
}

.container {
  overflow: visible;
}

/* Shield background */
.shield-track {
  fill: none;
  stroke: #d0d0d0;
  stroke-width: 2.5;
}

/* Animated shield border */
.shield {
  fill: none;
  stroke: #4f8cff;
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-dasharray: 30 70;
  animation: shieldMove 2s linear infinite;
}

/* Lock */
.lock-body {
  fill: #4f8cff;
  animation: lockPulse 1.5s ease-in-out infinite;
}

.lock {
  fill: none;
  stroke: #666;
  stroke-width: 2.5;
  stroke-linecap: round;
}

/* Keyhole */
.keyhole {
  fill: #fff;
  animation: keyPulse 1.5s ease-in-out infinite;
}

.keyhole-line {
  stroke: #fff;
  stroke-width: 2;
  stroke-linecap: round;
}

/* Scanning line */
.scan {
  stroke: #4f8cff;
  stroke-width: 1.5;
  stroke-linecap: round;
  opacity: 0;
  animation: scan 1.8s ease-in-out infinite;
}

/* Shield border movement */
@keyframes shieldMove {
  from {
    stroke-dashoffset: 100;
  }

  to {
    stroke-dashoffset: 0;
  }
}

/* Lock animation */
@keyframes lockPulse {
  0%,
  100% {
    opacity: 0.65;
    transform: scale(1);
    transform-origin: center;
  }

  50% {
    opacity: 1;
    transform: scale(1.08);
    transform-origin: center;
  }
}

/* Keyhole animation */
@keyframes keyPulse {
  0%,
  100% {
    opacity: 0.5;
  }

  50% {
    opacity: 1;
  }
}

/* Security scanner */
@keyframes scan {
  0% {
    opacity: 0;
    transform: translateY(-5px);
  }

  20% {
    opacity: 1;
  }

  80% {
    opacity: 1;
  }

  100% {
    opacity: 0;
    transform: translateY(35px);
  }
}
